pub fn solve(input: Value) -> Value {
    let s = input.as_str().unwrap();
    let mut result = String::new();
    let mut current = String::new();
    for c in s.chars() {
        if c.is_alphanumeric() {
            current.push(c);
        } else {
            if !current.is_empty() {
                result.push_str(&current);
                current.clear();
            }
            result.push(c);
        }
    }
    if !current.is_empty() {
        result.push_str(&current);
    }
    Value::String(result)
}
